-- Dữ liệu mẫu Listening + Grammar. Chạy SAU listening-grammar-depth.sql.
-- An toàn khi chạy lại: không ghi đè dữ liệu đã có (chỉ thêm bài tập cho chủ đề chưa có bài tập;
-- chỉ phân loại kỹ năng cho câu Listening còn ở giá trị mặc định DETAIL).
SET NAMES utf8mb4;


-- 1) Phân loại kỹ năng cho câu hỏi Listening hiện có (chỉ câu còn mặc định DETAIL).
UPDATE listening_questions SET skill_type = CASE
  WHEN LOWER(question_text) REGEXP 'main topic|mainly about|main idea' THEN 'MAIN_IDEA'
  WHEN LOWER(question_text) REGEXP 'most likely|imply|infer|reject|suggest' THEN 'INFERENCE'
  WHEN LOWER(question_text) REGEXP 'purpose|why is the (man|woman|speaker)|why should|why is .* calling' THEN 'PURPOSE'
  ELSE 'DETAIL' END
WHERE skill_type = 'DETAIL' AND listening_id BETWEEN 1000 AND 1023;


-- 2) Transcript + đoạn trích cho 2 bài mẫu đầu (chỉ khi chưa có transcript).
UPDATE listening_activities SET transcript = CONCAT(
 'Woman: Hello, this is Anna Cole. I am calling to reschedule my appointment with Dr. Lim.\n',
 'Man: Of course. Dr. Lim is unavailable on Thursday because she is attending a conference.\n',
 'Woman: I see. Could I come on Friday morning instead?\n',
 'Man: Yes, we have an opening at ten. I will come to your office to hand over the forms.')
WHERE id = 1000 AND (transcript IS NULL OR transcript = '');
UPDATE listening_questions SET transcript_excerpt = 'I am calling to reschedule my appointment with Dr. Lim.' WHERE id = 1000 AND transcript_excerpt IS NULL;
UPDATE listening_questions SET transcript_excerpt = 'Dr. Lim is unavailable on Thursday because she is attending a conference.' WHERE id = 1001 AND transcript_excerpt IS NULL;
UPDATE listening_questions SET transcript_excerpt = 'I will come to your office to hand over the forms.' WHERE id = 1002 AND transcript_excerpt IS NULL;
UPDATE listening_activities SET transcript = CONCAT(
 'Man: The photocopier on the third floor is broken again. We cannot print the reports.\n',
 'Woman: I will call the repair service this afternoon.\n',
 'Man: Thanks. I need the copies for the client presentation tomorrow.')
WHERE id = 1001 AND (transcript IS NULL OR transcript = '');
UPDATE listening_questions SET transcript_excerpt = 'The photocopier on the third floor is broken again.' WHERE id = 1003 AND transcript_excerpt IS NULL;
UPDATE listening_questions SET transcript_excerpt = 'I will call the repair service this afternoon.' WHERE id = 1004 AND transcript_excerpt IS NULL;
UPDATE listening_questions SET transcript_excerpt = 'I need the copies for the client presentation tomorrow.' WHERE id = 1005 AND transcript_excerpt IS NULL;


-- 3) Bài tập ngữ pháp mẫu cho các chủ đề (theo tiêu đề) chưa có bài tập.
DROP TEMPORARY TABLE IF EXISTS _seed_topics;
CREATE TEMPORARY TABLE _seed_topics (id BIGINT UNSIGNED PRIMARY KEY, title VARCHAR(300));
SELECT t.id, t.title FROM grammar_topics t
WHERE NOT EXISTS (SELECT 1 FROM grammar_exercises e WHERE e.grammar_topic_id = t.id);

DROP TEMPORARY TABLE IF EXISTS _seed_topics;
SELECT COUNT(*) AS grammar_exercises_total FROM grammar_exercises;
